const keys=new Set(),pointers=new Map(),actors=new Map();let socket=null,state=null,playerId=null,room='',yaw=0,lastStatus='',lastSend=0,lastFrame=0,watchIndex=0,drag=null;
const randomCode=()=>{const chars='ABCDEFGHJKLMNPQRSTUVWXYZ23456789',a=new Uint8Array(6);crypto.getRandomValues(a);return [...a].map(v=>chars[v%chars.length]).join('')};function send(data){if(socket?.readyState===WebSocket.OPEN)socket.send(JSON.stringify(data))}function reset(){keys.clear();pointers.clear();document.querySelectorAll('.pressed').forEach(b=>b.classList.remove('pressed'));sendInput()}function removeActors(){for(const actor of actors.values())scene.remove(actor.mesh);actors.clear()}
function connect(code){code=code.trim().toUpperCase();if(!/^[A-Z0-9]{4,8}$/.test(code)){$('#connection').textContent='Enter a room code with 4–8 letters or numbers.';return}if(socket){socket.close();socket=null}removeActors();state=null;playerId=null;lastStatus='';room=code;$('#connection').textContent='Connecting…';const ws=new WebSocket(`${location.protocol==='https:'?'wss:':'ws:'}//${location.host}/api/battle/${code}`);socket=ws;ws.addEventListener('message',e=>{if(ws!==socket)return;let m;try{m=JSON.parse(e.data)}catch{return}if(m.type==='joined'){playerId=m.id;$('#room-form').hidden=true;$('#lobby').hidden=false;$('#share-code').textContent=code;$('#room-label').textContent='ROOM '+code}else if(m.type==='notice')$('#lobby-status').textContent=m.message;else if(m.type==='snapshot'){const old=state?.status;state=m;drawTracers(m.tracers||[]);const me=m.players.find(p=>p.id===playerId);if(old!=='playing'&&m.status==='playing'&&me){yaw=me.yaw||0;watchIndex=0;reset()}refresh()}});ws.addEventListener('error',()=>{if(socket===ws)$('#connection').textContent='Could not connect. Check the code and try again.'});ws.addEventListener('close',()=>{if(socket!==ws)return;socket=null;state=null;playerId=null;reset();removeActors();overlay.hidden=false;stage.classList.add('intro');$('#title').textContent='Connection lost';$('#description').textContent='Check your connection and join again.';$('#room-form').hidden=false;$('#lobby').hidden=true;$('#connection').textContent='Your room code was '+room;$('#room-label').textContent='Disconnected'})}
function refresh(){if(!state)return;const me=state.players.find(p=>p.id===playerId);$('#room-label').textContent=`ROOM ${room} · ${state.players.length}/10`;$('#players-label').textContent=`${state.players.length} / 10 players · ${state.players.length%2?'one will watch':'even teams'}`;$('#red').textContent=state.scores.red;$('#blue').textContent=state.scores.blue;const spec=me?.team==='spectator';$('#next').hidden=!spec||state.status!=='playing';shoot.disabled=spec||state.status!=='playing'||me?.respawn>0;$('#role').textContent=spec?'Spectator':me?.team==='red'?'Red team':'Blue team';$('#health').textContent=spec?'Watching the match':me?.respawn>0?`Returning in ${Math.ceil(me.respawn)}…`:`${'♥ '.repeat(me?.hp||0)}${me?.protection>0?' · protected':''}`;if(state.status!==lastStatus){lastStatus=state.status;if(state.status==='playing'){overlay.hidden=true;stage.classList.remove('intro')}else if(state.status==='finished'||state.status==='ended'){overlay.hidden=false;stage.classList.add('intro');$('#room-form').hidden=true;$('#lobby').hidden=false;$('#title').textContent=state.status==='ended'?'Round ended':`${state.winner==='red'?'Red':'Blue'} team wins!`;$('#description').textContent=state.status==='ended'?'A team left the room. Start another round when everyone is ready.':`Final score: Red ${state.scores.red} · Blue ${state.scores.blue}.`;$('#start').textContent='Play again';reset()}}}
function has(k){return keys.has(k)||[...pointers.values()].includes(k)}function sendInput(){if(!state||!playerId)return;const me=state.players.find(p=>p.id===playerId);if(!me||me.team==='spectator')return;const f=Number(has('up'))-Number(has('down')),side=Number(has('right'))-Number(has('left'));send({type:'input',dx:-Math.sin(yaw)*f+Math.cos(yaw)*side,dz:-Math.cos(yaw)*f-Math.sin(yaw)*side,yaw,fire:has('fire')})}
