function frame(now){const dt=Math.min((now-lastFrame)/1000||0,.04);lastFrame=now;if(has('turnLeft'))yaw+=2*dt;if(has('turnRight'))yaw-=2*dt;if(state){const me=state.players.find(p=>p.id===playerId),players=state.players.filter(p=>p.team!=='spectator'),spectating=me?.team==='spectator',watched=spectating?players[watchIndex%Math.max(players.length,1)]:me;const present=new Set();for(const p of players){present.add(p.id);let a=actors.get(p.id);if(!a||a.team!==p.team){if(a)scene.remove(a.mesh);a={team:p.team,mesh:person(p.team)};a.mesh.position.set(p.x,0,p.z);actors.set(p.id,a)}a.mesh.position.x+=(p.x-a.mesh.position.x)*.35;a.mesh.position.z+=(p.z-a.mesh.position.z)*.35;a.mesh.rotation.y=p.yaw+Math.PI;a.mesh.visible=p.id!==watched?.id&&p.respawn<=0;}for(const [id,a] of actors)if(!present.has(id)){scene.remove(a.mesh);actors.delete(id)}const a=watched&&actors.get(watched.id);if(a){camera.position.set(a.mesh.position.x,1.72,a.mesh.position.z);camera.rotation.set(0,spectating?watched.yaw:yaw,0,'YXZ')}held.visible=!!watched&&watched.respawn<=0&&state.status==='playing';if(spectating&&watched)$('#health').textContent=`Watching ${watched.team.toUpperCase()} · Player ${watched.slot}`;$('#banner').hidden=!(me?.respawn>0&&!spectating);if(me?.respawn>0)$('#banner').textContent=`Returning in ${Math.ceil(me.respawn)}…`;}else{camera.position.set(-10,18,40);camera.lookAt(0,0,0);held.visible=false}if(now-lastSend>80){lastSend=now;sendInput()}renderer.render(scene,camera);requestAnimationFrame(frame)}
